-- Read-only capability audit; no raw import data, credentials, IPs or full asset payloads.
BEGIN READ ONLY;
WITH e AS (SELECT item_uid,asset_type,COALESCE(payload,'{}')||COALESCE(payload->'fields','{}') AS p FROM cmdb_entity WHERE asset_type IN ('rack','server','switch','gpu','nic','pdu','environment_sensor')),
fields AS (SELECT t.asset_type,t.key,count(*) AS total,count(*) FILTER (WHERE e.p->>t.key IS NOT NULL AND e.p->>t.key <> '') AS present FROM e JOIN (VALUES
('rack','u_height'),('rack','pod_id'),('rack','depth_mm'),('rack','power_capacity_kw'),('rack','power_used_kw'),('rack','position'),
('server','rack_id'),('server','rack_u'),('server','u_start'),('server','u_height'),('server','mounting_face'),('server','face'),('server','depth_mm'),('server','is_full_depth'),('server','panel_front'),('server','panel_back'),('server','gpu_count'),('server','gpu_model'),('server','cpu'),('server','memory_gb'),('server','model'),('server','observed_at'),
('switch','rack_id'),('switch','rack_u'),('switch','u_height'),('switch','face'),('switch','mounting_face'),('switch','depth_mm'),('switch','is_full_depth'),('switch','panel_front'),('switch','panel_back'),('switch','model')
) AS t(asset_type,key) ON e.asset_type=t.asset_type GROUP BY t.asset_type,t.key)
SELECT json_build_object('field_coverage',(SELECT json_agg(fields ORDER BY asset_type,key) FROM fields),'counts',(SELECT json_object_agg(asset_type,n) FROM (SELECT asset_type,count(*) n FROM cmdb_entity GROUP BY asset_type) s),'location_relations',(SELECT json_agg(s) FROM (SELECT fact_layer,source_type,count(*) FROM cmdb_relationship WHERE definition_id='located_in' AND valid_to IS NULL GROUP BY fact_layer,source_type)s),'position_sources',(SELECT json_agg(s) FROM (SELECT field_name,fact_layer,approval_status,support,freshness,count(*) FROM cmdb_field_source WHERE field_name IN ('rack_id','rack_u','u_start','u_height','mounting_face','face','depth_mm','panel_front','panel_back') GROUP BY 1,2,3,4,5)s),'samples',(SELECT json_agg(s) FROM (SELECT item_uid,asset_type,p->>'model' model,p->>'rack_id' rack_id,p->>'rack_u' rack_u,p->>'u_height' u_height,p->>'gpu_count' gpu_count,p->>'face' face FROM e WHERE item_uid IN ('rack-0001','srv-0001','sw-leaf-0001'))s),'active_schema',(SELECT id FROM cmdb_schema_version WHERE status='active'),'model_revision_count',(SELECT count(*) FROM device_model_revision),'rack_placement_count',(SELECT count(*) FROM rack_placement),'bom_revision_count',(SELECT count(*) FROM bom_revision));
COMMIT;
